using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
namespace BF4Bots {public static partial class OneClick {
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr window,System.Text.StringBuilder text,int count);
 [DllImport("user32.dll")]static extern bool EnumChildWindows(IntPtr parent,EnumWindow callback,IntPtr state);
 [DllImport("user32.dll")]static extern bool IsWindowEnabled(IntPtr window);
 [DllImport("user32.dll")]static extern bool PostMessage(IntPtr window,uint message,IntPtr w,IntPtr l);
 public static void SignInBattlelog(string root,Action<string> progress){PrepareLocal(root,progress);string launcher=Path.Combine(root,"BF4Launcher.exe");var current=At(launcher);if(current.Count==0){Process.Start(new ProcessStartInfo(launcher){WorkingDirectory=root,UseShellExecute=true,WindowStyle=ProcessWindowStyle.Minimized});WaitOwner(32170,launcher,30,progress);current=At(launcher);}if(current.Count!=1)throw new IOException("Não há um único launcher auxiliar para entrar no Battlelog.");int pid=current[0].Id;var buttons=new System.Collections.Generic.List<IntPtr>();EnumWindows((window,s)=>{uint owner;GetWindowThreadProcessId(window,out owner);if(owner==(uint)pid)EnumChildWindows(window,(child,state)=>{var caption=new System.Text.StringBuilder(256);GetWindowText(child,caption,caption.Capacity);if(caption.ToString().Trim()=="Sign in to Battlelog")buttons.Add(child);return true;},IntPtr.Zero);return true;},IntPtr.Zero);if(buttons.Count!=1||!IsWindowEnabled(buttons[0]))throw new IOException("O componente original não disponibilizou a entrada no Battlelog. Tente novamente após o carregamento.");if(!PostMessage(buttons[0],0x00F5,IntPtr.Zero,IntPtr.Zero))throw new IOException("Não consegui encaminhar o pedido ao launcher auxiliar.");HideHelpers(root);}
 delegate bool EnumWindow(IntPtr window,IntPtr state);
 [DllImport("user32.dll")]static extern bool EnumWindows(EnumWindow callback,IntPtr state);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr window,out uint processId);
 public static void ClosePreviousPanels(){string folder=Path.GetDirectoryName(System.Windows.Forms.Application.ExecutablePath);foreach(string name in new[]{"BF4BotLauncher","BF4BotLauncher-v1.1","BF4BotLauncher-v1.2"})foreach(var p in Process.GetProcessesByName(name)){try{if(SamePath(p.MainModule.FileName,Path.Combine(folder,name+".exe"))||SamePath(p.MainModule.FileName,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Desktop),"BF4 Bot Launcher",name+".exe")))p.CloseMainWindow();}catch{}}}
 public static void HideHelpers(string root){var ids=At(Path.Combine(root,"BF4Launcher.exe")).Concat(At(Path.Combine(root,"Server\\BF4BlazeServer.exe"))).Concat(At(Path.Combine(root,"Server\\bf4_Server_Final.exe"))).Select(p=>p.Id).ToArray();EnumWindows((h,s)=>{uint pid;GetWindowThreadProcessId(h,out pid);if(ids.Contains((int)pid))ShowWindowAsync(h,0);return true;},IntPtr.Zero);}
 public static void PrepareLocal(string root,Action<string> progress){Config.ValidateRoot(root);var cfg=Settings.Read(root);if(Settings.Get(cfg,"BlazeIP","127.0.0.1")!="127.0.0.1")return;string backend=Path.Combine(root,"Server\\BF4BlazeServer.exe"),server=Path.Combine(root,"Server\\bf4_Server_Final.exe");var b=File.ReadAllText(Path.Combine(root,"Server\\config.txt"));int bp=Port(b,"ClientPort",10040),rp=Int32.Parse(Settings.Get(cfg,"RconPort","25210"));progress("Preparando backend local…");Ensure(backend,bp,()=>Process.Start(new ProcessStartInfo(backend){WorkingDirectory=Path.Combine(root,"Server"),UseShellExecute=true,WindowStyle=ProcessWindowStyle.Hidden}),progress,30);progress("Preparando servidor local…");Ensure(server,rp,()=>Server.Start(root,null),progress,90);}
 public static void StopLocalServer(string root){string server=Path.Combine(root,"Server\\bf4_Server_Final.exe");foreach(var p in At(server))CloseVerified(p,server);}
 public static void ReloadOriginal(string root){string game=Path.Combine(root,"bf4_no_drm.exe");if(At(game).Count>0)throw new InvalidOperationException("Feche o jogo para recarregar o launcher auxiliar.");string launcher=Path.Combine(root,"BF4Launcher.exe");foreach(var p in At(launcher))CloseVerified(p,launcher);}
}}
